cat > /workspace/cmd/peco/main.go << 'EOFMAIN'
package main

import (
	"bufio"
	"flag"
	"fmt"
	"io"
	"os"
	"os/signal"
	"regexp"
	"strings"
	"syscall"

	"github.com/gdamore/tcell/v2"
	"github.com/mattn/go-runewidth"
)

const version = "v0.5.11"

var (
	helpFlag          = flag.Bool("h", false, "show this help message and exit")
	helpFlag2         = flag.Bool("help", false, "show this help message and exit")
	queryFlag         = flag.String("query", "", "initial value for query")
	rcfileFlag        = flag.String("rcfile", "", "path to the settings file")
	versionFlag       = flag.Bool("version", false, "print the version and exit")
	bufferSizeFlag    = flag.Int("b", 0, "number of lines to keep in search buffer")
	bufferSizeFlag2   = flag.Int("buffer-size", 0, "number of lines to keep in search buffer")
	nullFlag          = flag.Bool("null", false, "expect NUL (\\0) as separator for target/output")
	initialIndexFlag  = flag.Int("initial-index", 0, "position of the initial index of the selection (0 base)")
	initialFilterFlag = flag.String("initial-filter", "", "specify the default filter")
	promptFlag        = flag.String("prompt", "", "specify the prompt string")
	layoutFlag        = flag.String("layout", "top-down", "layout to be used")
	select1Flag       = flag.Bool("select-1", false, "select first item and immediately exit if the input contains only 1 item")
	exit0Flag         = flag.Bool("exit-0", false, "exit immediately with status 1 if the input is empty")
	selectAllFlag     = flag.Bool("select-all", false, "select all items and immediately exit")
	onCancelFlag      = flag.String("on-cancel", "success", "specify action on user cancel")
	selectionPrefixFlag = flag.String("selection-prefix", "", "use a prefix instead of changing line color")
	execFlag          = flag.String("exec", "", "execute command instead of finishing/terminating peco")
	printQueryFlag    = flag.Bool("print-query", false, "print out the current query as first line of output")
	ansiFlag          = flag.Bool("ansi", false, "enable ANSI color code support")
	heightFlag        = flag.String("height", "", "display height in lines or percentage")
)

type Peco struct {
	lines         []string
	filteredLines []string
	query         string
	selectedIndex int
	scrollOffset  int
	screen        tcell.Screen
	width         int
	height        int
	filterType    string
	nullSeparator bool
}

func main() {
	flag.Parse()

	if *helpFlag || *helpFlag2 {
		printHelp()
		os.Exit(0)
	}

	if *versionFlag {
		fmt.Printf("peco version %s (built with go%s)\n", version, "1.25.0")
		os.Exit(0)
	}

	// Read input
	var lines []string
	separator := "\n"
	if *nullFlag {
		separator = "\x00"
	}

	scanner := bufio.NewScanner(os.Stdin)
	if *nullFlag {
		scanner.Buffer(make([]byte, 0, 64*1024), 64*1024)
		scanner.Split(func(data []byte, atEOF bool) (advance int, token []byte, err error) {
			for i := 0; i < len(data); i++ {
				if data[i] == '\x00' {
					return i + 1, data[:i], nil
				}
			}
			if !atEOF {
				return 0, nil, nil
			}
			return len(data), data, io.EOF
		})
	}

	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}

	if *bufferSizeFlag == 0 {
		*bufferSizeFlag = *bufferSizeFlag2
	}
	if *bufferSizeFlag > 0 && len(lines) > *bufferSizeFlag {
		lines = lines[:*bufferSizeFlag]
	}

	// Handle special cases
	if len(lines) == 0 && *exit0Flag {
		os.Exit(0)
	}

	if len(lines) == 1 && *select1Flag {
		if *printQueryFlag {
			fmt.Println()
		}
		fmt.Print(lines[0])
		if !*nullFlag {
			fmt.Println()
		} else {
			fmt.Print("\x00")
		}
		os.Exit(0)
	}

	if *selectAllFlag {
		if *printQueryFlag {
			fmt.Println()
		}
		for i, line := range lines {
			fmt.Print(line)
			if i < len(lines)-1 {
				if *nullFlag {
					fmt.Print("\x00")
				} else {
					fmt.Println()
				}
			} else {
				if *nullFlag {
					fmt.Print("\x00")
				} else {
					fmt.Println()
				}
			}
		}
		os.Exit(0)
	}

	// Initialize TUI
	screen, err := tcell.NewScreen()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: failed to initialize screen: %v\n", err)
		os.Exit(1)
	}
	defer screen.Fini()

	if err := screen.Init(); err != nil {
		fmt.Fprintf(os.Stderr, "Error: failed to initialize screen: %v\n", err)
		os.Exit(1)
	}

	width, height := screen.Size()

	peco := &Peco{
		lines:        lines,
		query:        *queryFlag,
		selectedIndex: 0,
		screen:       screen,
		width:        width,
		height:       height,
		filterType:   "IgnoreCase",
		nullSeparator: *nullFlag,
	}

	// Initial filtering
	peco.updateFiltered()

	// Handle resize
	go func() {
		sigChan := make(chan os.Signal, 1)
		signal.Notify(sigChan, syscall.SIGWINCH)
		for range sigChan {
			newWidth, newHeight := screen.Size()
			if newWidth != peco.width || newHeight != peco.height {
				peco.width = newWidth
				peco.height = newHeight
				peco.draw()
			}
		}
	}()

	// Main event loop
	for {
		peco.draw()

		ev := screen.PollEvent()
		if ev == nil {
			continue
		}

		switch ev := ev.(type) {
		case *tcell.EventKey:
			switch ev.Key() {
			case tcell.KeyCtrlC, tcell.KeyEscape:
				if *onCancelFlag == "error" {
					os.Exit(1)
				}
				os.Exit(0)
			case tcell.KeyEnter:
				peco.selectCurrent()
				return
			case tcell.KeyUp:
				if peco.selectedIndex > 0 {
					peco.selectedIndex--
					peco.ensureVisible()
				}
			case tcell.KeyDown:
				if peco.selectedIndex < len(peco.filteredLines)-1 {
					peco.selectedIndex++
					peco.ensureVisible()
				}
			case tcell.KeyCtrlU:
				peco.query = ""
				peco.selectedIndex = 0
				peco.scrollOffset = 0
				peco.updateFiltered()
			case tcell.KeyBackspace, tcell.KeyBackspace2:
				if len(peco.query) > 0 {
					peco.query = peco.query[:len(peco.query)-1]
					peco.selectedIndex = 0
					peco.scrollOffset = 0
					peco.updateFiltered()
				}
			case tcell.KeyRune:
				peco.query += string(ev.Rune())
				peco.selectedIndex = 0
				peco.scrollOffset = 0
				peco.updateFiltered()
			case tcell.KeyPageUp:
				peco.selectedIndex = peco.selectedIndex - (peco.height - 2)
				if peco.selectedIndex < 0 {
					peco.selectedIndex = 0
				}
				peco.ensureVisible()
			case tcell.KeyPageDown:
				peco.selectedIndex = peco.selectedIndex + (peco.height - 2)
				if peco.selectedIndex >= len(peco.filteredLines) {
					peco.selectedIndex = len(peco.filteredLines) - 1
				}
				peco.ensureVisible()
			case tcell.KeyHome:
				peco.selectedIndex = 0
				peco.scrollOffset = 0
			case tcell.KeyEnd:
				peco.selectedIndex = len(peco.filteredLines) - 1
				peco.ensureVisible()
			}
		case *tcell.EventResize:
			peco.width, peco.height = ev.Size()
		}
	}
}

func (p *Peco) updateFiltered() {
	p.filteredLines = p.lines
	if p.query == "" {
		return
	}

	queries := strings.Fields(p.query)
	for _, q := range queries {
		p.filteredLines = p.filterLines(p.filteredLines, q)
	}
}

func (p *Peco) filterLines(lines []string, query string) []string {
	var result []string
	q := strings.ToLower(query)
	for _, line := range lines {
		if strings.Contains(strings.ToLower(line), q) {
			result = append(result, line)
		}
	}
	return result
}

func (p *Peco) ensureVisible() {
	displayLines := p.height - 2
	if displayLines <= 0 {
		displayLines = 1
	}

	if p.selectedIndex < p.scrollOffset {
		p.scrollOffset = p.selectedIndex
	}
	if p.selectedIndex >= p.scrollOffset+displayLines {
		p.scrollOffset = p.selectedIndex - displayLines + 1
	}
}

func (p *Peco) draw() {
	p.screen.Clear()

	// Draw query line
	queryText := fmt.Sprintf("QUERY> %s", p.query)
	if len(queryText) > p.width {
		queryText = queryText[:p.width]
	}

	for i, ch := range queryText {
		if i >= p.width {
			break
		}
		p.screen.SetContent(i, 0, ch, nil, tcell.StyleDefault)
	}

	// Draw status
	statusText := fmt.Sprintf("%s [%d (1/%d)]", "IgnoreCase", len(p.filteredLines), len(p.lines))
	statusX := p.width - len(statusText)
	if statusX < 0 {
		statusX = 0
	}
	for i, ch := range statusText {
		x := statusX + i
		if x >= p.width {
			break
		}
		p.screen.SetContent(x, 0, ch, nil, tcell.StyleDefault)
	}

	// Draw lines
	displayLines := p.height - 2
	if displayLines <= 0 {
		displayLines = 1
	}

	for i := 0; i < displayLines && p.scrollOffset+i < len(p.filteredLines); i++ {
		line := p.filteredLines[p.scrollOffset+i]
		y := i + 1

		style := tcell.StyleDefault
		if p.scrollOffset+i == p.selectedIndex {
			style = style.Reverse(true)
		}

		for j, ch := range line {
			if j >= p.width {
				break
			}
			p.screen.SetContent(j, y, ch, nil, style)
		}

		// Fill rest of line
		for j := len(line); j < p.width; j++ {
			p.screen.SetContent(j, y, ' ', nil, style)
		}
	}

	p.screen.Show()
}

func (p *Peco) selectCurrent() {
	if len(p.filteredLines) == 0 {
		os.Exit(0)
	}

	if p.selectedIndex >= len(p.filteredLines) {
		p.selectedIndex = len(p.filteredLines) - 1
	}

	if *printQueryFlag {
		fmt.Println(p.query)
	}

	line := p.filteredLines[p.selectedIndex]
	fmt.Print(line)
	if !p.nullSeparator {
		fmt.Println()
	} else {
		fmt.Print("\x00")
	}

	os.Exit(0)
}

func printHelp() {
	fmt.Printf(`
Usage: peco [options] [FILE]

Options:
  -h, --help            show this help message and exit
  --query               initial value for query
  --rcfile              path to the settings file
  --version             print the version and exit
  -b, --buffer-size     number of lines to keep in search buffer
  --null                expect NUL (\0) as separator for target/output
  --initial-index       position of the initial index of the selection (0 base)
  --initial-filter      specify the default filter
  --prompt              specify the prompt string
  --layout              layout to be used. 'top-down', 'bottom-up', or 'top-down-query-bottom'. default is 'top-down'
  --select-1            select first item and immediately exit if the input contains only 1 item
  --exit-0              exit immediately with status 1 if the input is empty
  --select-all          select all items and immediately exit
  --on-cancel           specify action on user cancel. 'success' or 'error'.
                        default is 'success'. This may change in future versions
  --selection-prefix    use a prefix instead of changing line color to indicate currently selected lines.
                        default is to use colors. This option is experimental
  --exec                execute command instead of finishing/terminating peco.
                        Please note that this command will receive selected line(s) from stdin,
                        and will be executed via '/bin/sh -c' or 'cmd /c'
  --print-query         print out the current query as first line of output
  --ansi                enable ANSI color code support
  --height              display height in lines or percentage (e.g. '10', '50%')
`)
}
EOFMAIN

