		if *printQueryFlag {
			fmt.Println()
		}
		fmt.Print(lines[0])
		if !*nullFlag {
			fmt.Println()
		} else {
			fmt.Print("\x00")
		}
		os.Exit(0)
	}

	if *selectAllFlag {
		if *printQueryFlag {
			fmt.Println()
		}
		for i, line := range lines {
			fmt.Print(line)
			if i < len(lines)-1 {
				if *nullFlag {
					fmt.Print("\x00")
				} else {
					fmt.Println()
				}
			} else {
				if *nullFlag {
					fmt.Print("\x00")
				} else {
					fmt.Println()
				}
			}
		}
		os.Exit(0)
	}

	width, height := getTerminalSize()

	tui := &TUI{
		lines:        lines,
		query:        *queryFlag,
		selectedIndex: 0,
		width:        width,
		height:       height,
		nullSeparator: *nullFlag,
	}

	// Initial filtering
	tui.updateFiltered()

	// Enter raw mode and run TUI
	tui.run()
}

func (t *TUI) updateFiltered() {
	t.filteredLines = t.lines
	if t.query == "" {
		return
	}

	queries := strings.Fields(t.query)
	for _, q := range queries {
		t.filteredLines = t.filterLines(t.filteredLines, q)
	}
}

func (t *TUI) filterLines(lines []string, query string) []string {
	var result []string
	q := strings.ToLower(query)
	for _, line := range lines {
		if strings.Contains(strings.ToLower(line), q) {
			result = append(result, line)
		}
	}
	return result
}

func (t *TUI) run() {
	// Initialize terminal
	initTerminal()
	defer restoreTerminal()

	t.draw()

	// Simple loop - just read one character and exit
	var buf [1]byte
	for {
		n, err := os.Stdin.Read(buf[:])
		if n > 0 || err != nil {
			switch buf[0] {
			case 3: // Ctrl-C
				if *onCancelFlag == "error" {
					os.Exit(1)
				}
				os.Exit(0)
			case 13: // Enter
				t.selectCurrent()
				return
			case 27: // Escape
				if *onCancelFlag == "error" {
					os.Exit(1)
				}
				os.Exit(0)
			}
		}
	}
}

func (t *TUI) draw() {
	fmt.Print("\033[2J\033[H") // Clear screen and move cursor to top
	fmt.Printf("QUERY> %s\n", t.query)
	for _, line := range t.filteredLines {
		fmt.Println(line)
	}
}

