	if len(t.filteredLines) == 0 {
		os.Exit(0)
	}

	if t.selectedIndex >= len(t.filteredLines) {
		t.selectedIndex = len(t.filteredLines) - 1
	}

	if *printQueryFlag {
		fmt.Println(t.query)
	}

	line := t.filteredLines[t.selectedIndex]
