				p.height = newH
				p.draw()
			}
		}
	}()

	p.draw()

	// Handle input
	buf := make([]byte, 1)
	prevByte := byte(0)
	escapeSeq := false

	for {
		n, _ := os.Stdin.Read(buf[:])
		if n == 0 {
			continue
		}

		key := buf[0]

		// Handle escape sequences
