				case 65: // Up arrow
					if p.selectedIndex > 0 {
						p.selectedIndex--
						p.ensureVisible()
						p.draw()
					}
				case 66: // Down arrow
					if p.selectedIndex < len(p.filteredLines)-1 {
						p.selectedIndex++
						p.ensureVisible()
						p.draw()
					}
				case 72: // Home
					p.selectedIndex = 0
					p.scrollOffset = 0
					p.draw()
				case 70: // End
					p.selectedIndex = len(p.filteredLines) - 1
					p.ensureVisible()
					p.draw()
