	queries := strings.Fields(p.query)
	for _, q := range queries {
		p.filteredLines = p.filterLines(p.filteredLines, q)
	}

	if p.selectedIndex >= len(p.filteredLines) {
		p.selectedIndex = len(p.filteredLines) - 1
		if p.selectedIndex < 0 {
			p.selectedIndex = 0
		}
	}
}

func (p *Peco) filterLines(lines []string, query string) []string {
	var result []string
	q := strings.ToLower(query)
	for _, line := range lines {
		if strings.Contains(strings.ToLower(line), q) {
			result = append(result, line)
		}
	}
	return result
}

func (p *Peco) run() {
	// Setup terminal
	if runtime.GOOS != "windows" {
		// Set raw mode
		enableRawMode()
		defer disableRawMode()
	}

	// Handle signals for resize
	sigch := make(chan os.Signal, 1)
	signal.Notify(sigch, syscall.SIGWINCH)
	go func() {
		for range sigch {
			newW, newH := getTerminalSize()
			if newW != p.width || newH != p.height {
				p.width = newW
				p.height = newH
				p.draw()
			}
		}
	}()

	p.draw()

	// Handle input
	buf := make([]byte, 1)
	prevByte := byte(0)
	escapeSeq := false

	for {
		n, _ := os.Stdin.Read(buf[:])
		if n == 0 {
			continue
		}

		key := buf[0]

		// Handle escape sequences
		if key == 27 { // ESC
			escapeSeq = true
			continue
		}

		if escapeSeq {
			if key == 91 { // [ after ESC
				prevByte = key
				continue
			}
			if prevByte == 91 { // CSI sequence
				switch key {
				case 65: // Up arrow
					if p.selectedIndex > 0 {
						p.selectedIndex--
						p.ensureVisible()
						p.draw()
					}
				case 66: // Down arrow
					if p.selectedIndex < len(p.filteredLines)-1 {
						p.selectedIndex++
						p.ensureVisible()
						p.draw()
					}
				case 72: // Home
					p.selectedIndex = 0
					p.scrollOffset = 0
					p.draw()
				case 70: // End
					p.selectedIndex = len(p.filteredLines) - 1
					p.ensureVisible()
					p.draw()
				}
				escapeSeq = false
				prevByte = 0
				continue
			}
		}

		switch key {
		case 3: // Ctrl-C
			p.cancelSelection()
			return
		case 13: // Enter
			p.selectCurrent()
			return
		case 127, 8: // Backspace
			if len(p.query) > 0 {
				p.query = p.query[:len(p.query)-1]
				p.selectedIndex = 0
				p.scrollOffset = 0
				p.updateFiltered()
				p.draw()
			}
		case 21: // Ctrl-U
			p.query = ""
			p.selectedIndex = 0
			p.scrollOffset = 0
			p.updateFiltered()
			p.draw()
		default:
			if key >= 32 && key < 127 {
				p.query += string(key)
				p.selectedIndex = 0
				p.scrollOffset = 0
				p.updateFiltered()
				p.draw()
			}
		}
	}
}

