func (p *Peco) updateFiltered() {
	p.filteredLines = p.lines
	if p.query == "" {
		return
	}

	queries := strings.Fields(p.query)
	for _, q := range queries {
		p.filteredLines = p.filterLines(p.filteredLines, q)
	}

	if p.selectedIndex >= len(p.filteredLines) {
		p.selectedIndex = len(p.filteredLines) - 1
		if p.selectedIndex < 0 {
			p.selectedIndex = 0
		}
	}
}

func (p *Peco) filterLines(lines []string, query string) []string {
	var result []string
	q := strings.ToLower(query)
	for _, line := range lines {
		if strings.Contains(strings.ToLower(line), q) {
			result = append(result, line)
		}
	}
	return result
}

func (p *Peco) run() {
	// Setup terminal
	if runtime.GOOS != "windows" {
		// Set raw mode
		enableRawMode()
		defer disableRawMode()
	}

	// Handle signals for resize
	sigch := make(chan os.Signal, 1)
	signal.Notify(sigch, syscall.SIGWINCH)
	go func() {
		for range sigch {
			newW, newH := getTerminalSize()
			if newW != p.width || newH != p.height {
				p.width = newW
				p.height = newH
				p.draw()
			}
		}
	}()

	p.draw()

	// Handle input
	buf := make([]byte, 1)
	prevByte := byte(0)
	escapeSeq := false

	for {
		n, _ := os.Stdin.Read(buf[:])
		if n == 0 {
			continue
		}

		key := buf[0]

		// Handle escape sequences
		if key == 27 { // ESC
			escapeSeq = true
			continue
		}

		if escapeSeq {
			if key == 91 { // [ after ESC
				prevByte = key
				continue
			}
			if prevByte == 91 { // CSI sequence
				switch key {
				case 65: // Up arrow
					if p.selectedIndex > 0 {
						p.selectedIndex--
						p.ensureVisible()
						p.draw()
					}
				case 66: // Down arrow
					if p.selectedIndex < len(p.filteredLines)-1 {
						p.selectedIndex++
						p.ensureVisible()
						p.draw()
					}
				case 72: // Home
					p.selectedIndex = 0
					p.scrollOffset = 0
					p.draw()
				case 70: // End
					p.selectedIndex = len(p.filteredLines) - 1
					p.ensureVisible()
					p.draw()
				}
				escapeSeq = false
				prevByte = 0
				continue
			}
		}

		switch key {
		case 3: // Ctrl-C
			p.cancelSelection()
			return
		case 13: // Enter
			p.selectCurrent()
			return
		case 127, 8: // Backspace
			if len(p.query) > 0 {
				p.query = p.query[:len(p.query)-1]
				p.selectedIndex = 0
				p.scrollOffset = 0
				p.updateFiltered()
				p.draw()
			}
		case 21: // Ctrl-U
			p.query = ""
			p.selectedIndex = 0
			p.scrollOffset = 0
			p.updateFiltered()
			p.draw()
		default:
			if key >= 32 && key < 127 {
				p.query += string(key)
				p.selectedIndex = 0
				p.scrollOffset = 0
				p.updateFiltered()
				p.draw()
			}
		}
	}
}

func (p *Peco) ensureVisible() {
	displayLines := p.height - 2
	if displayLines <= 0 {
		displayLines = 1
	}

	if p.selectedIndex < p.scrollOffset {
		p.scrollOffset = p.selectedIndex
	}
	if p.selectedIndex >= p.scrollOffset+displayLines {
		p.scrollOffset = p.selectedIndex - displayLines + 1
	}
}

func (p *Peco) draw() {
	// Clear screen
	fmt.Print("\033[2J\033[H")

	// Draw query line
	queryText := fmt.Sprintf("QUERY> %s", p.query)
	if len(queryText) > p.width {
		queryText = queryText[:p.width]
	}

	// Draw status on the same line as query
	statusText := fmt.Sprintf("%s [%d (1/%d)]", p.filterType, len(p.filteredLines), len(p.lines))
	spaces := p.width - len(queryText) - len(statusText)
	if spaces < 0 {
		spaces = 0
	}

	fmt.Print(queryText)
	for i := 0; i < spaces; i++ {
		fmt.Print(" ")
	}
	fmt.Println(statusText)

	// Draw filtered lines
	displayLines := p.height - 2
	if displayLines <= 0 {
		displayLines = 1
	}

	for i := 0; i < displayLines && p.scrollOffset+i < len(p.filteredLines); i++ {
		line := p.filteredLines[p.scrollOffset+i]

		// Highlight selected line
		if p.scrollOffset+i == p.selectedIndex {
			fmt.Print("\033[7m") // Reverse video
		}

		// Truncate line if too long
		if len(line) > p.width {
			line = line[:p.width]
		}
		fmt.Print(line)

		// Reset style and fill rest of line
		fmt.Print("\033[0m")
		for j := len(line); j < p.width; j++ {
			fmt.Print(" ")
		}

		fmt.Println()
	}
}

func (p *Peco) selectCurrent() {
	if len(p.filteredLines) == 0 {
		os.Exit(0)
	}

	if p.selectedIndex >= len(p.filteredLines) {
		p.selectedIndex = len(p.filteredLines) - 1
	}

	if *printQueryFlag {
		fmt.Println(p.query)
	}

	line := p.filteredLines[p.selectedIndex]
	os.Stdout.WriteString(line)
	if *nullFlag {
		os.Stdout.WriteString("\x00")
	} else {
		os.Stdout.WriteString("\n")
	}
	os.Stdout.Sync()

	os.Exit(0)
}

func (p *Peco) cancelSelection() {
	if *onCancelFlag == "error" {
		os.Exit(1)
	}
	os.Exit(0)
}

func getTerminalSize() (int, int) {
	var ws Winsize
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, uintptr(1), 0x5413, uintptr(unsafe.Pointer(&ws)))
	if err == 0 {
		return int(ws.Cols), int(ws.Rows)
	}
	return 80, 24
}

func enableRawMode() {
	// Save original settings and enable raw mode
	cmd := exec.Command("stty", "-g")
	out, _ := cmd.Output()
	sttyOriginal = string(out)

	exec.Command("stty", "-icanon", "-echo", "cbreak").Run()
}

func disableRawMode() {
	// Restore original settings
	if sttyOriginal != "" {
		exec.Command("stty", sttyOriginal).Run()
	} else {
		exec.Command("stty", "icanon", "echo", "-cbreak").Run()
	}
}

